UPDATE library_content SET body='Mộc là dự án thư viện cho mượn, bán sách tại quầy và cung cấp nội dung đọc online có quyền sử dụng.\n\nBạn đọc có thể tìm sách, lưu yêu thích, theo dõi hạn trả, đánh giá và chia sẻ cảm nhận.\n\nThông tin trên website phục vụ bản học tập; các thông tin vận hành có thể được nhóm điều chỉnh trước khi sử dụng thực tế.' WHERE slug='gioi-thieu' AND body='Mộc là dự án thư viện cho mượn, bán sách tại quầy và cung cấp nội dung đọc online có quyền sử dụng.\n\nBạn đọc có thể tìm sách, lưu yêu thích, theo dõi hạn trả, đánh giá và chia sẻ cảm nhận.\n\nThông tin trên website phục vụ bản demo học tập; các thông tin vận hành có thể được nhóm điều chỉnh trước khi sử dụng thực tế.';
UPDATE library_content SET body='Hỗ trợ bạn đọc\n\nKhi liên hệ, cung cấp mã phiếu hoặc mã giao dịch cùng nội dung cần hỗ trợ. Không gửi mật khẩu, mã OTP hay khóa API.\n\nĐây là trang liên hệ của dự án. Quản trị cần cập nhật địa chỉ, điện thoại, email và giờ mở cửa thực tế tại Cấu hình thư viện trước khi vận hành.' WHERE slug='lien-he' AND body='Hỗ trợ bạn đọc\n\nKhi liên hệ, cung cấp mã phiếu hoặc mã giao dịch cùng nội dung cần hỗ trợ. Không gửi mật khẩu, mã OTP hay khóa API.\n\nĐây là trang liên hệ mẫu của dự án. Quản trị cần cập nhật địa chỉ, điện thoại, email và giờ mở cửa thực tế tại Cấu hình thư viện trước khi vận hành.';
